INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (1, '400', '/lore/400/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (2, 'Académie de l’arcane', '/lore/academie-de-larcane/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (3, 'Accessoires', '/ressources/accessoires/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (4, 'Acquis', NULL, 'Les points d’une compétence qui ne se répartissent pas, mais se gagnent : par l’entraînement, les dons de la race, de l’ethnie et de la classe, l’armure portée, le métier et les accessoires, et la fiche de personnage du site les additionne. En règle générale, ils ne dépassent pas 5 par point de la caractéristique, le +1 de la magie innée compris.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (5, 'Action', NULL, 'L’action principale du tour, qui sert à attaquer, à lancer un sort, à utiliser un objet, à sprinter, à utiliser un don de type Action ou à faire une quatrième action rapide.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (8, 'Alchimie', '/ressources/alchimie/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (9, 'Alchimie primitive', '/ressources/alchimie-primitive/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (10, 'Alignement', '/regles/alignement/', 'Moralité et Éthique du personnage. Évolue en fonction des actes accomplis selon les deux axes Bon/Mauvais et Loyal/Chaotique', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (11, 'Altération d’état', '/regles/alterations-d-etats/', 'Un changement de la condition d’un personnage (poison, brûlure, peur, paralysie…) qui lui inflige des malus, souvent pendant plusieurs tours. Il en existe vingt, physiques ou mentales, et la plupart ont trois stades, de plus en plus forts.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (12, 'Âme', NULL, '{{cout-secondaire|Ressource secondaire}} de la {{magie-de-la-necromancie|nécromancie}}. C’est une réserve de 10 unités par défaut. Elle est utilisé pour la plupart des sorts en plus du {{chakra|chakra}}. La réserve d''âmes se recharge de 1 par tour en combat.', 'magie:necromancie', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (13, 'Amélioration', NULL, 'Le niveau d’une arme (de +1 à +10), d’une armure ou d’un bouclier (de +1 à +5). Le niveau choisi donne le bonus qu’il écrit, qui est déjà le total : +10 aux dégâts pour une arme +5, +10 AP et +10 AM pour une armure +5, +10 AP pour un bouclier +5. On paie toutes les étapes, une à une, sans en sauter aucune. Les crans de {{solidite|solidité}} : pour une arme, +1 du +5 au +9 et +2 au +10 ; pour une armure, +1 au +4 comme au +5 ; pour un bouclier, les crans s’additionnent, +1 du +1 au +4 et +2 au +5.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (14, 'Anansi', '/races/anansi/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (15, 'Anansi', '/classes/anansi/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (16, 'Anna', '/lore/anna/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (17, 'Arbalétrier', '/classes/arbaletrier/', NULL, 'classe:distance', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (18, 'Archer', '/classes/archer/', NULL, 'classe:distance', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (19, 'Archimage', '/classes/archimage/', NULL, 'classe:speciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (20, 'Armes', '/ressources/armes/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (21, 'Armure magique', NULL, 'Les points que l’armure retire aux dégâts des attaques magiques.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (22, 'Armure physique', NULL, 'Les points que l’armure retire aux dégâts des attaque physiques.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (23, 'Armures', '/ressources/armures/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (24, 'Armurier', '/metiers/#metier-armurier', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (25, 'Artisanat', '/regles/artisanat/', 'Fabriquer des objets, ce que seuls certains métiers permettent : il faut le bon métier. La compétence d’artisanat vaut 10 × la première caractéristique du métier + 10 × la seconde.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (26, 'Attaque discrète', '/regles/les-attaques-discretes/', 'Frapper une cible qui ne vous voit pas venir, pour un dé de dégâts en plus. À ne pas confondre avec l’attaque sournoise, qui vient d’une classe.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (27, 'Attaque d’opportunité', '/regles/les-attaques-d-opportunite/', 'Une attaque offerte hors de son tour, quand un adversaire rate son attaque contre vous sur un échec critique, quand il sort de votre zone d’influence (sauf si c’est vous qui l’en faites sortir), ou quand un don le permet. Une seule par tour et par joueur, sauf don qui en permet plus, et seulement une action simple.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (28, 'Se défendre', '/regles/attaque-et-defense/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (29, 'Attaque gratuite', NULL, 'L’attaque que permet un adversaire qui quitte votre {{zone-dinfluence|zone d’influence}} : c’est une {{attaque-dopportunite|attaque d’opportunité}}, avec ses limites.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (30, 'Attaquer', '/regles/attaquer-et-se-defendre/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (31, 'Attributs', NULL, 'Les valeurs de base du personnage (santé, {{chakra|chakra}}, {{barriere|barrière}}, {{corruption|corruption}}, vitesse, initiative, armure de base), et la quatrième barre pour la Nécromancie et la magie du Sang.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (32, 'Aurora', '/lore/aurora/', NULL, 'magie:lumiere', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (33, 'Balogne', '/lore/balogne/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (34, 'Barde', '/classes/barde/', NULL, 'classe:magiques', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (35, 'Bardiche du Bourreau déchiré', '/lore/bardiche-du-bourreau-dechire/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (36, 'Barrage Argenté', '/lore/barrage-argente/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (37, 'Barrière', NULL, 'Manifestation physique dérivée du {{chakra|Chakra}} d''un individu. Elle agit comme une seconde peau invisible protégeant le corps de blessures. Abrégée BA, elle vaut la moitié du {{chakra|chakra}} total, arrondie à l’inférieur, plus les bonus de la race et de la classe. Sauf indication contraire, elle prend les coups avant la santé.', 'attribut:barriere', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (38, 'Bâton de la destruction', '/lore/baton-de-la-destruction/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (39, 'Bâton magique', '/ressources/objets-a-la-ceinture/#batons-magiques', 'Catalyseur à conserver à la ceinture pour améliorer l''usage de la magie.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (40, 'Battlemap', NULL, 'Voir {{carte-de-combat|Carte de combat}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (41, 'Bauc', '/lore/bauc/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (42, 'Bestiaire', '/bestiaire/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (43, 'Biclassage', NULL, 'Personnage ayant de choisir de suivre la voie de deux classes en simultanée.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (44, 'Bienvenue dans Maverick', '/decouvrir/', NULL, 'partie:decouvrir', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (45, 'Bimane', '/classes/bimane/', NULL, 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (46, 'Blessure et mort', '/regles/blessures-et-etats/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (47, 'Bois du printemps', '/lore/bois-du-printemps/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (48, 'Boss', NULL, 'Un ennemi pensé pour affronter une équipe de quatre joueurs. Il a deux initiatives par tour, et plus de parades et d’esquives que les autres dans certaines postures.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (49, 'Bouclier', '/ressources/bouclier/', 'Une forme, sa classe de 1 à 5 (Bocle, Targe, Bouclier Rond, Écu, Pavois), et une matière, qui donne sa solidité. Ses AP et son AM ne comptent que sur une parade partielle faite avec lui, et son poids demande une Force minimum.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (50, 'Brock', '/lore/brock/', NULL, 'magie:sang', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (51, 'Mêlée', NULL, 'Désigne une {{portee|Portée}} de 1, dans une case directement adjacente.', 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (52, 'Camnau', '/lore/camnau/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (53, 'Campagne', NULL, 'Une aventure en plusieurs séances, qui part d’un point A pour arriver à un point B ; les joueurs y font partie de l’écriture de l’histoire. Voir aussi {{one-shot|One shot}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (54, 'Don', NULL, 'Compétence d''une race ou d''une classe.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (55, 'Capse', '/lore/capse/', NULL, 'magie:espace-temps', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (56, 'Caractéristique', NULL, '{{force|Force}}, {{volonte|Volonté}}, {{intelligence|Intelligence}}, {{perception|Perception}}, {{social|Social}} et / ou {{agilite|Agilité}}, pouvant aller de 1 à 4 hors magie innée. Certaines {{race|races}} limites d''avantage ces valeurs', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (57, 'Carte de combat', NULL, 'Une carte quadrillée vue de haut, où le MJ dessine les obstacles d’un combat et où l’on compte les distances en cases. Il peut s’en passer pour un combat rapide.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (58, 'Ceinture', '/ressources/objets-a-la-ceinture/', 'Trois emplacements pour des objets à portée de main (fioles, carquois, bâtons magiques…), qui s’utilisent en une action rapide au lieu d’une action entière ; au plus 3 exemplaires du même objet dans chacun.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (59, 'Celsius', '/lore/celsius/', NULL, 'magie:glace', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (60, 'Chakra', NULL, 'Énergie consommée lors de l''utilisation de magie. Quand le chakra est épuisé, la santé est consommée à la hauteur de 3 points pour un de Chakra. Abrégé CK, il compte les points de magie du personnage, que dépensent ses sorts, et vient de la race, de la ou des classes et des magies.', 'attribut:chakra', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (61, 'Champicer', '/lore/champicer/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (62, 'Champieu', '/lore/champieu/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (63, 'Chapelle des Os', '/lore/chapelle-des-os/', NULL, 'magie:necromancie', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (64, 'Chargement (Mage Vert)', '/capacites/mage-vert-chargement/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (65, 'Chronologie', '/chronologie/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (66, 'Classe', '/classes/', 'La façon de se battre du personnage. Elle a son propre niveau, et lui donne de la santé, du {{chakra|chakra}} et de la {{barriere|barrière}}, des maîtrises d’armes et d’armures, un équipement de départ et des dons. Les classes se rangent en cinq catégories : physiques au corps à corps, physiques à distance, magiques, raciales et spéciales.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (67, 'Classe magique', NULL, 'Une classe de la catégorie des classes magiques ; l’Archimage, rangée dans les classes spéciales, en est une aussi. Elle donne 4 AM et compte comme une condition pour les emplacements de sorts. La seconde spécialité de chaque classe raciale, et celle du Flagelleur, compte elle aussi comme classe magique : elle donne 4 AM et compte comme une condition pour les emplacements de sorts.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (68, 'Classe raciale', NULL, 'La classe propre à une race hybride, qui porte son nom. Le Drassah’thac, hybride, n’en a pas.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (69, 'Clerc', '/classes/clerc/', NULL, 'classe:magiques', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (70, 'Cloche d’or', '/lore/cloche-dor/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (71, 'codex', '/lore/codex/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (72, 'Collines humides', '/lore/collines-humides/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (73, 'Coma', NULL, 'L’état d’un personnage dont la santé tombe à 0 ou moins. Inconscient, il fait des jets de Survie : un seul réussi le stabilise, trois ratés et il meurt.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (74, 'Compagnie du Fer Noir', '/lore/compagnie-du-fer-noir/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (75, 'Compétence', NULL, 'Un savoir-faire lié à une {{caracteristique|Caractéristique}}, dont le score est déterminé par un score {{naturel|Naturel}} et un score {{acquis|Acquis}}, ainsi qu''un bonus variable en fonction de la situation. Détermine un pourcentage de réussite.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (76, 'Composants', '/ressources/composants/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (77, 'Confrérie du Sang', '/lore/confrerie-du-sang/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (78, 'Corruption', NULL, 'Poison du {{chakra|chakra}} : chaque point de corruption prend la place d''un point de chakra, jusqu''au maximum du chakra ; le repos et la méditation ne la font pas baisser. Au maximum, le personnage a deux semaines pour en retirer un point, sinon il meurt et devient une abomination à moins d''en maîtriser la {{magie-de-la-corruption|magie}}', 'magie:corruption', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (79, 'Coût secondaire', NULL, 'Ce qu’un sort coûte en plus de son {{chakra|chakra}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (80, 'Couturier', '/metiers/#metier-couturier', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (81, 'Créature invoquée', NULL, 'Une créature appelée par un sort. Elle n’a pas d’échelle de puissance. Sa puissance est indexée sur le {{niveau-de-puissance-magique|NPM}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (82, 'Créer son personnage', '/regles/creer-son-personnage/', NULL, 'partie:creer', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (83, 'Croc du Volcan', '/lore/croc-du-volcan/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (84, 'Croix', NULL, 'Une marque altérant durablement une {{caracteristique|Caractéristique}} donnée. Une croix retire 20 % à tous les jets de la caractéristique. Deux la rendent inutilisable, elle et les compétences liées.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (85, 'Cuirassé', '/classes/cuirasse/', NULL, 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (86, 'Défense partielle', NULL, 'Une parade ou une esquive réussie, mais moins bonne que l’attaque. Les dégâts sont divisés par 2. Si c’est une parade partielle faite au bouclier, ses AP et son AM comptent : c’est le seul cas où ils comptent. Contre une réussite critique, seule une défense critique peut être partielle.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (87, 'Dégâts', '/regles/les-degats/', 'Ce que perd la cible d’un coup réussi, en santé ou en {{barriere|barrière}}, une fois retirée son armure.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (88, 'Dés', '/regles/jet-de-des/', 'Un jet de dés détermine l''issue d''une action aux conséquences incertaines.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (89, 'Dieu choisi', NULL, 'Dieu ou déesse que le personnage a choisi de prier en plus de son dieu ou sa déesse {{dieu-inne|inné(e)}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (90, 'Dieu inné', NULL, 'Affinité particulière avec la divinité lié à la {{magie-innee|Magie innée}} du personnage', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (91, 'Dimitri', '/lore/dimitri/', NULL, 'magie:terre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (92, 'distance', NULL, NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (93, 'Dombourg', '/lore/dombourg/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (95, 'Don de base', NULL, 'Le don que donne la race, Méditation (pour récupérer du {{chakra|chakra}}) ou Repos (pour récupérer de la santé et du {{chakra|chakra}}) ; une action, trois fois par jour.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (96, 'Donjon Pas bon', '/regles/donjon-pas-bon/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (97, 'Double coup (Mage Rouge)', '/capacites/mage-rouge-double-coup/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (98, 'Double coup (Mage Vert)', '/capacites/mage-vert-double-coup/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (99, 'Dragon', '/lore/dragon/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (100, 'Drakos', '/races/drakos/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (101, 'Drassah', '/lore/drassah/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (102, 'Drassah''thac', '/races/drassahthac/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (103, 'Eaunoire', '/lore/eaunoire/', NULL, 'magie:corruption', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (104, 'Échec critique', NULL, 'Un résultat de 96 à 100 au D100. L’action rate complètement, et cela coûte quelque chose : un sort au double de son coût, une défense où l’armure ne compte plus…', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (105, 'Échelle de puissance', NULL, 'Puissance approximative d''un monstre, de 1 à 10. 
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (106, 'Église du Sel', '/lore/eglise-du-sel/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (107, 'Eirnn', '/lore/eirnn/', NULL, 'magie:ombre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (108, 'Elfe argenté', '/races/elfe-argente/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (109, 'Elfe doré', '/races/elfe-dore/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (110, 'Elfe forestier', '/races/elfe-forestier/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (111, 'Elfe noir', '/races/elfe-noir/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (112, 'Embuscade', '/regles/l-embuscade/', 'Consommer l’action de son tour pour attendre un ennemi, et lui porter une attaque d’opportunité dès qu’il entre dans la zone voulue. La posture de vigilance la déjoue.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (113, 'Empire Argenté', '/lore/empire-argente/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (114, 'Empire Humain', '/lore/empire-humain/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (115, 'Emplacement de sort', NULL, 'Leur nombre déterminer combien de sorts différents un personnage peut utiliser parmi la listes des sorts connus. Augmenté par le {{niveau-de-puissance-magique|NPM}} du personnage et par le fait d''avoir accès à une {{magie-acquise|Magie acquise}} ou à la {{super-magie|Super Magie}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (116, 'Entraînement', NULL, 'Un jet de D100 qui fait gagner des points d’acquis dans une compétence, auprès d’un entraîneur ou d’un PNJ important. Il ne fait progresser que 15 compétences au plus, et chacune de 10 % au plus.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (117, 'Éoline', '/lore/eoline/', NULL, 'magie:vent', NULL);
