INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (120, 'Esquive', NULL, 'Éviter un coup, avec la compétence Esquive (Agilité). Voir aussi {{parade|Parade}} et {{defense-partielle|Défense partielle}}.', 'caracteristique:agilite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (121, 'Étape 1 : imaginer son personnage et choisir sa race', '/regles/choisir-sa-race/', NULL, 'partie:creer', NULL);
