INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (162, 'Initiative', NULL, 'Ce qui fixe l’ordre de jeu en combat. À chaque tour, chacun lance 1D20 et ajoute un bonus qui dépend de son Agilité ; on joue du plus haut résultat au plus bas.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (163, 'Instant Cast', NULL, 'Une action qui ne prend pas l’action du tour. Trois au plus par tour, jamais deux fois la même, toujours avant l’action ; un sort IC ne consomme pas le tour, sauf sur un échec critique.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (164, 'Intervention', NULL, 'En posture défensive, parer ou esquiver un coup à la place d’un allié adjacent.', NULL, NULL);
