INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (206, 'Mage Vert', '/classes/mage-vert/', NULL, 'classe:magiques', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (207, 'Magie acquise', '/magies/', 'Magie secondaire apprise par l''expérience. Donne accès à plus de sort, mais ferme la voie à la {{super-magie|Super Magie}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (208, 'Magie de la Corruption', '/magies/magie-de-la-corruption/', 'Magie primordiale, elle manipule la {{corruption|Corruption}} dans sa forme pure et brute. Elle consume et empoisonne.  Augmente l''{{intelligence|Intelligence}}.', 'magie:corruption', 'magie:corruption');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (209, 'Magie de la Foudre', '/magies/magie-de-la-foudre/', 'Magie élémentaire, vive et impulsive pour des esprits prompts à l''action. Augmente l''{{agilite|Agilité}}.', 'magie:foudre', 'magie:foudre');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (210, 'Magie de la Glace', '/magies/magie-de-la-glace/', 'Magie élémentaire, imperturbable. Un rempart rigide pour refroidir les ardeurs d''un assaillant. Augmente l''{{intelligence|Intelligence}}.', 'magie:glace', 'magie:glace');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (211, 'Magie de la Lumière', '/magies/magie-de-la-lumiere/', 'Magie élémentaire, aussi appelée magie sacrée, capable de protection, guérison, sacrifice de soit et fanatisme aveugle.  Augmente la {{perception|Perception}}.', 'magie:lumiere', 'magie:lumiere');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (212, 'Magie de la Nécromancie', '/magies/magie-de-la-necromancie/', 'Magie primordiale de la Mort, tout aussi employer pour asservir les non-morts que pour guider les âmes vers l''au-delà. Augmente la {{volonte|volonté}}.', 'magie:necromancie', 'magie:necromancie');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (213, 'Magie de la Terre', '/magies/magie-de-la-terre/', 'Magie élémentaire, liée à la nature et la roche, s''érigeant en protecteur inflexible. Augmente la {{force|Force}}.', 'magie:terre', 'magie:terre');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (214, 'Magie de l''Arcane', '/magies/magie-de-larcane/', 'Magie primordiale, elle manipule le {{chakra|Chakra}} dans sa forme pure et brute. Malléable et polyvalente.  Augmente l''{{intelligence|Intelligence}}.', 'magie:arcane', 'magie:arcane');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (215, 'Magie de l''Eau', '/magies/magie-de-leau/', 'Magie élémentaire, stable et impassible, peut tout aussi bien soigner que déchaîner la fureur des océans.  Augmente le {{social|Social}}.', 'magie:eau', 'magie:eau');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (216, 'Magie de l''Espace/Temps', '/magies/magie-de-lespace-temps/', 'Magie primordiale complexe et rigide, remaniant les loi de la physique. Faible en apparence, elle est l''outils parfait des stratèges.  Augmente l''{{intelligence|Intelligence}}.', 'magie:espace-temps', 'magie:espace-temps');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (217, 'Magie de l''Ombre', '/magies/magie-de-lombre/', 'Magie élémentaire sournoise orientée vers les entraves, la ruse et des secrets. Augmente la {{perception|Perception}}.', 'magie:ombre', 'magie:ombre');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (218, 'Magie du Feu', '/magies/magie-du-feu/', 'Magie élémentaire, destructrice et impulsive, faite pour réagir à l''instinct. Augmente le {{social|Social}}.', 'magie:feu', 'magie:feu');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (219, 'Magie du Sang', '/magies/magie-du-sang/', 'Magie primordiale, sauvage et combative. Renforce directement le physique.  Augmente la {{force|Force}}.', 'magie:sang', 'magie:sang');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (220, 'Magie du Vent', '/magies/magie-du-vent/', 'Magie élémentaire liée au cieux, aux grands espaces et à la vitesse. Augmente l''{{agilite|Agilité}}.', 'magie:vent', 'magie:vent');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (221, 'Magie du Vide', '/magies/magie-du-vide/', 'Magie primordiale, tordant l''esprit et la réalité, neutralisant les autres magies. Augmente la {{volonte|volonté}}.', 'magie:vide', 'magie:vide');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (222, 'Magie innée', '/magies/', 'Magie héritée à la naissance depuis l''un des deux parents. Influence fortement l''apparence du personnage et lui donne une caractéristique spécifique', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (223, 'Magies', '/magies/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (224, 'magique', NULL, NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (225, 'Maître du jeu', NULL, 'Celui qui raconte l’histoire, joue les PNJ et les monstres, et juge de ce qui est possible, improbable ou impossible.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (226, 'Maîtrise d’arme', NULL, 'Le savoir-faire avec une catégorie d’arme. Sans maîtrise, l’arme lance 1 dé de dégâts ; chaque point de maîtrise en ajoute un, jusqu’à 4 points au plus par catégorie, donc 5 dés. Les points de toutes les sources s’additionnent, jusqu’à ce plafond ; au-delà, la fiche le signale, et les points en trop ne donnent pas de dé.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (227, 'Majin', '/races/majin/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (228, 'Maladie', '/ressources/maladie/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (229, 'Marais fangeux', '/lore/marais-fangeux/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (230, 'Marais vert', '/lore/marais-vert/', NULL, NULL, NULL);
