INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (240, 'Métier', '/metiers/', 'Un savoir-faire choisi à la création ou plus tard dans l’aventure. Il donne des bonus d’acquis ou d’attribut, des objets de départ et, pour certains, l’artisanat.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (241, 'Mineur', '/metiers/#metier-mineur', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (242, 'Minotaure', '/races/minotaure/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (243, 'Minotaure', '/classes/minotaure/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (244, 'Mirada', '/lore/mirada/', NULL, 'magie:arcane', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (245, 'Mode Hyper', '/regles/le-mode-hyper/', 'État de surpuissance. Pour quelques tours, une fois par semaine, la magie du personnage ne fait plus qu’un avec lui.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (246, 'Mode Super', '/regles/mode-super/', 'Un équivalent moins puissant du Mode Hyper : une symbiose avec un objet légendaire ou enchanté.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (247, 'Moine', '/classes/moine/', NULL, 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (248, 'Mont cendré', '/lore/mont-cendre/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (249, 'Monts Couloirs', '/lore/monts-couloirs/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (250, 'Mora', '/lore/mora/', NULL, 'magie:vide', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (251, 'Mordhau', NULL, 'Avec certaines armes de corps à corps (notamment les épées), prendre l''arme par la lame et frapper avec le manche. Elle peut ainsi faire des dégâts de frappe alors qu''elle en est incapable, mais a 30 % de chance de perdre un cran de solidité (exemple : plus de 70 au jet d''attaque).', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (252, 'Morfot', '/lore/morfot/', NULL, 'magie:potentiel-illimite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (253, 'Mort-vivant', '/races/mort-vivant/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (254, 'Mrode', '/lore/mrode/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (255, 'Nain', '/races/nain/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (256, 'Namazu', '/races/namazu/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (257, 'Namazu', '/classes/namazu/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (258, 'Naturel', NULL, 'Les points de compétence que l’on répartit soi-même, à la création (100 points, 20 au plus dans une compétence) puis à chaque niveau.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (259, 'Négatif maximal', NULL, 'L’opposé de la santé maximum (−30 pour 30 de santé). Un personnage dans le coma qui y descend n’a droit qu’à un seul jet de survie, et à deux fois ce négatif, il meurt sur le coup.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (260, 'Niveau de classe', NULL, 'Le niveau propre à chaque classe, qui suit le niveau global. La classe donne ses dons à ses niveaux 1, 5, 10, 15 et 20, et sa spécialité à son niveau 10.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (261, 'Niveau de maîtrise', NULL, 'Niveau de maîtrise d''un sort de 0 à 3, permettant d''en lancer un version améliorée. L''amélioration dépends du sort.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (262, 'Niveau de puissance magique', NULL, 'Le niveau d’un sort, de 1 à 5. Un sort n’est accessible que si la puissance magique du personnage atteint son NPM.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (263, 'Niveau global', NULL, 'Le niveau du personnage, de 1 à 20, que fixe son total d’expérience. Il règle le niveau de ses classes et sa puissance magique.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (264, 'Notix', '/lore/notix/', NULL, 'magie:espace-temps', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (265, 'Océane', '/lore/oceane/', NULL, 'magie:eau', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (266, 'Ocultomancien', '/classes/ocultomancien/', NULL, 'classe:magiques', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (267, 'Olwman', '/races/olwman/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (268, 'Olwman', '/classes/olwman/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (269, 'One shot', NULL, 'Une histoire jouée en une seule séance, avec une fin fermée, qui ne laisse pas de suite. Voir aussi {{campagne|Campagne}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (270, 'Onir', '/lore/onir/', NULL, 'magie:ombre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (271, 'Ordre de Gardecroc', '/lore/ordre-de-gardecroc/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (272, 'Ordre de la Glace Rouge', '/lore/ordre-de-la-glace-rouge/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (273, 'Ordre de la mort', '/lore/ordre-de-la-mort/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (274, 'Ordre des Abeilles', '/lore/ordre-des-abeilles/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (275, 'Ordre du brai', '/lore/ordre-du-brai/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (276, 'Ordre Solaire', '/lore/ordre-solaire/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (277, 'Origine du monde', '/lore/origine-du-monde/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (278, 'Orios', '/races/orios/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (279, 'Orios', '/classes/orios/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (280, 'Parade', NULL, 'Bloquer un coup avec son arme ou son bouclier, avec la compétence Parade (Force). Voir aussi {{esquive|Esquive}} et {{defense-partielle|Défense partielle}}.', 'caracteristique:force', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (281, 'Parleur', '/classes/parleur/', NULL, 'classe:speciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (282, 'Personnage joueur', NULL, 'Un personnage joueur, celui qu’incarne un joueur ; un personnage non joueur, que joue le MJ, comme tous ceux que croisent les personnages.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (283, 'Personnage non joueur', NULL, 'Voir {{personnage-joueur|Personnage joueur}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (284, 'Pièce élémentaire', '/ressources/armes/#pieces-elementaires', 'Une pièce qui, posée sur une arme, une armure ou un vêtement, le transforme pour toujours en un équipement chargé de sa magie ; les bonus d’origine sont perdus.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (285, 'Plaine brillante', '/lore/plaine-brillante/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (286, 'Plaines sèches', '/lore/plaines-seches/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (287, 'Plateau Tonnerre', '/lore/plateau-tonnerre/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (288, 'Points d’expérience', NULL, 'Les points d’expérience. Leur total fixe le niveau global.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (289, 'Portée', NULL, 'Donne la distance où une arme, une action ou un sort peut faire effet.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (290, 'Posture', '/regles/les-postures/', 'L’attitude de combat que l’on prend ou change au début de son tour : on garde sa posture tant qu’on n’en change pas. Il en existe six : Offensif, Défensif, Neutre, Focus, Vigilance et Symbiose.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (291, 'Potentiel illimité', '/magies/potentiel-illimite/', 'Magie unique donnant accès aux sort de toutes les magies au prix d''un épuisement physique constant.', 'magie:potentiel-illimite', 'magie:potentiel-illimite');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (292, 'Pierre précieuse', NULL, 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 PP = 1 000 RO.', NULL, 'monnaie:pp');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (293, 'Préparation (Mage Rouge)', '/capacites/mage-rouge-preparation/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (294, 'Prétiré', NULL, 'Une fiche de personnage créée sur le site, visible de tous ; la liste des personnages les réunit.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (295, 'Prise en tenaille', NULL, 'Voir {{tenaille|Tenaille}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (296, 'Pugiliste', '/classes/pugiliste/', NULL, 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (297, 'Puissance magique', NULL, 'Le niveau de magie du personnage, de 1 à 5, qui augmente avec son niveau global. Elle dit jusqu’à quel NPM il peut lancer des sorts, et multiplie ses emplacements de sorts.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (298, 'Race', '/races/', 'Ensemble d''individus issus d''une même lignée commune', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (299, 'Race pure', NULL, 'En opposition aux races dites {{hybride-animal|hybride animal}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (300, 'Rater ses sortilèges', '/regles/rater-ses-sortileges/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (301, 'Recharge longue', NULL, 'Doit utiliser son action ou son mouvement pour recharger. Une propriété de certaines armes.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (302, 'Recharge très longue', NULL, 'Doit utiliser son action ET son mouvement pour recharger. Une propriété de certaines armes.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (303, 'Règles des métiers', '/metiers/regles-des-metiers/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (304, 'Relations entre les races', '/lore/relations-entre-les-races/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (305, 'Remède', NULL, 'Une potion contre une altération d’état. Le mineur la réduit d’un cran, le majeur de deux, le parfait la soigne entièrement.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (306, 'République Forestier', '/lore/republique-forestier/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (307, 'République Noire', '/lore/republique-noire/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (308, 'Résistance magique', NULL, 'Réduit les dégâts subit de manière croissante avec le niveau de résistance (avant réduction par l''armure) : 
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (309, 'Résistances et faiblesses', '/regles/resistances-et-faiblesses/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (310, 'Réussir une action', '/regles/reussir-une-action/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (311, 'Réussite critique', NULL, 'Un résultat de 1 à 5 au D100, que des bonus élargissent (posture, score au-delà de 95 %, dons, sorts…), jamais au-delà de 1 à 15. L’action réussit de façon exceptionnelle : en attaque, les dégâts, bonus fixes compris, sont doublés.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (312, 'Ricken de fer', NULL, 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 RO = 100 RF.', NULL, 'monnaie:rf');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (313, 'Ricken d’or', NULL, 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 RO = 100 RF, et 1 PP = 1 000 RO.', NULL, 'monnaie:ro');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (314, 'Rokh', '/races/rokh/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (315, 'Rokh', '/classes/rokh/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (316, 'Ruines Rouges', '/lore/ruines-rouges/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (317, 'Sang', NULL, '{{cout-secondaire|Ressource secondaire}} de la {{magie-du-sang|magie du Sang}}. C’est une réserve de 10 unités par défaut. Elle est utilisé pour la plupart des sorts en plus du {{chakra|chakra}}. La réserve de sang se recharge de 1 par tour en combat.', 'magie:sang', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (318, 'Santé', NULL, 'Les points de vie du personnage. À 0 ou moins, il tombe dans le coma.', 'attribut:sante', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (319, 'Satyre', '/races/satyre/', NULL, 'race:hybride', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (320, 'Satyre', '/classes/satyre/', NULL, 'classe:raciales', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (321, 'Saugnane', '/lore/saugnane/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (322, 'Scénario one shot', NULL, 'Voir {{one-shot|One shot}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (323, 'Score', NULL, 'Le pourcentage de réussite d’une compétence, qui vaut 10 × la caractéristique + les points naturels + les points acquis. Il faut faire son score ou moins au D100 pour réussir.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (324, 'Selcalibur', '/lore/selcalibur/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (325, 'S’entraîner', '/regles/s-entrainer-et-exercer-un-metier/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (326, 'Séraphe', '/lore/seraphe/', NULL, 'magie:sang', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (327, 'Séraphin', '/lore/seraphin/', NULL, 'magie:feu', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (328, 'Signe des pirates', '/lore/signe-des-pirates/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (329, 'Situation actuelle', '/lore/situation-actuelle/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (330, 'Soir-matin', '/lore/soir-matin/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (331, 'Solidité', NULL, 'État de l''équipement. Une Solidité à 0 rend l''objet inutilisable et exige une réparation.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (332, 'Sort fer', NULL, 'Type de sort d''amélioration qui s''applique sur une arme. Faisant qu''elle inflige désormais des dégâts magiques.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (333, 'Sort grenade', NULL, 'Type particulier de sort provoquant une explosion localisée.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (334, 'spéciale', NULL, NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (335, 'Spécialité', NULL, 'L’embranchement d’une classe, qui se choisit quand elle atteint le niveau 10 ; la page de la classe en donne les dons.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (336, 'Sprint', NULL, 'Doubler la distance parcourue pendant son tour. C’est l’action du tour : impossible d’attaquer après un sprint.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (337, 'Super Gemme', '/lore/super-gemme/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (338, 'Temple de la Foudre', '/lore/temple-de-la-foudre/', NULL, 'magie:foudre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (339, 'Temple de la Glace', '/lore/temple-de-la-glace/', NULL, 'magie:glace', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (340, 'Temple de la Lumière', '/lore/temple-de-la-lumiere/', NULL, 'magie:lumiere', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (341, 'Temple de la Terre', '/lore/temple-de-la-terre/', NULL, 'magie:terre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (342, 'Temple de l’Eau', '/lore/temple-de-leau/', NULL, 'magie:eau', NULL);
