INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (344, 'Temple de l’Ombre', '/lore/temple-de-lombre/', NULL, 'magie:ombre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (345, 'Temple de Vent', '/lore/temple-de-vent/', NULL, 'magie:vent', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (346, 'Temple du Feu', '/lore/temple-du-feu/', NULL, 'magie:feu', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (347, 'Temple du Savoir', '/lore/temple-du-savoir/', NULL, 'magie:vide', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (348, 'Temple noir', '/lore/temple-noir/', NULL, 'magie:corruption', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (349, 'Temples/Cultes/Guildes', '/lore/temples-cultes-guildes/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (350, 'Tenaille', '/regles/prise-en-tenaille-et-zone-d-influence/', 'Un ennemi encerclé au corps à corps par des alliés placés sur des cases opposées ; chaque allié de plus donne un avantage, jusqu’à quatre.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (351, 'Terre grise', '/lore/terre-grise/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (352, 'Tisseurs de soi', '/lore/tisseurs-de-soi/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (353, 'Tofrom', '/lore/tofrom/', NULL, 'magie:potentiel-illimite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (354, 'Tounne', '/lore/tounne/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (355, 'Tour', NULL, 'En combat, le temps se découpe en tours ; chacun agit à son tour, dans l’ordre de l’initiative, puis un nouveau tour commence.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (356, 'Tour de charge', NULL, 'Un sort qui requiert un tour de charge doit prendre un tour complet sans interruption avant d''être lancé. Annulé par la posture focus', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (357, 'Tueur', '/classes/tueur/', NULL, 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (358, 'Umbro', '/lore/umbro/', NULL, 'magie:ombre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (359, 'Un maître du Jeu', '/mj/un-maitre-du-jeu/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (360, 'Vampires primordiaux', '/lore/vampires-primordiaux/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (361, 'Ville-Oeil', '/lore/ville-oeil/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (362, 'Vitesse', NULL, 'Le nombre de cases que le personnage parcourt en un tour. Divisé entre vitesse au sol, et vitesse de nage.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (363, 'Voleur', '/classes/voleur/', NULL, 'classe:melee', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (364, 'Volt', '/lore/volt/', NULL, 'magie:foudre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (365, 'Vulnérabilité Magique', NULL, 'Augmente les dégâts subit de manière croissante avec le niveau de vulnérabilité (avant réduction par l''armure) :
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (366, 'Xendown', '/lore/xendown/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (367, 'Zone d’influence', NULL, 'Les cases devant un adversaire, derrière lui, à sa gauche et à sa droite. Y entrer puis la traverser, ou la quitter, lui permet une {{attaque-dopportunite|attaque d’opportunité}}, avec ses limites.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (368, 'Agilité', NULL, '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{arme-legere|Arme Légère}}, {{equilibre|Équilibre}}, {{esquive|Esquive}}, {{reflexe|Réflexe}} et {{ruse|Ruse}}. Renforée par les magies {{magie-innee|innées}} du {{magie-du-vent|Vent}} ou de la {{magie-de-la-foudre|Foudre}}', 'caracteristique:agilite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (369, 'Ambidextrie', NULL, 'Une arme de mêlée dans chaque main : −20 % à l’attaque de la main directrice, −40 % à celle de la main secondaire ; le malus est divisé par deux pour la main qui tient une dague et par deux pour la classe Bimane, les deux se cumulant.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (370, 'Arbalète', NULL, 'Une compétence liée aux armes qui tirent des carreaux. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (371, 'Arc', NULL, 'Une compétence liée aux armes qui tirent des flèches. Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (372, 'Arme Légère', NULL, 'Une compétence liée à l’utilisation d’arme de catégorie légère. Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (373, 'Arme Lourde', NULL, 'Une compétence liée à l’utilisation d’arme de catégorie lourde. Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (374, 'Athlétisme', NULL, 'Utilisée lors de tests où la force pure est mise à l''épreuve. (équivalent d’équilibre pour l’agilité) Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (375, 'Calme', NULL, 'Faire preuve de sang-froid dans les situations dangereuses. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (376, 'Concentration', NULL, 'Permet de rester concentré sur son sort (utilisé par les mages rouge, bleu et vert pour lancer leurs sorts). Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (377, 'Connaissance', NULL, 'Une grande connaissance sur de vastes sujets. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (378, 'Diplomatie', NULL, 'Persuader sans violence, ni contrainte. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (379, 'Distinction', NULL, 'L''art de voir les choses en profondeur, de sentir, d''écouter, de ressentir. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (380, 'Dressage', NULL, 'Liée au dressage d''animaux ou monstres destinés à être des familiers. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (381, 'Équilibre', NULL, 'L''art de garder l’équilibre dans différentes situations. (équivalent d’athlétisme pour la force) Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (382, 'Fermeté', NULL, 'Mieux résister aux attaques mentales, aux attaques sur le psychique. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (383, 'Force', NULL, '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{arc|Arc}}, {{arme-lourde|Arme Lourde}}, {{athletisme|Athlétisme}}, {{parade|Parade}} et {{stabilite|Stabilité}}. Renforée par les magies {{magie-innee|innées}} du {{magie-du-sang|Sang}} ou de la {{magie-de-la-terre|Terre}}', 'caracteristique:force', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (384, 'Intelligence', NULL, '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{connaissance|Connaissance}}, {{magie|Magie}}, {{medecine|Médecine}}, {{psychologie|Psychologie}} et {{vie-en-nature|Vie en nature}}}. Renforcée par les magies {{magie-innee|innées}} de l''{{magie-de-larcane|Arcane}}, de la {{magie-de-la-corruption|Corruption}}, de l''{{magie-de-lespace-temps|Espace/Temps}} ou de la{{magie-de-la-glace|Glace}}', 'caracteristique:intelligence', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (385, 'Intimidation', NULL, 'Persuader avec violence, sous la contrainte. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (386, 'Jet d’attaque', NULL, 'Le D100 de l’attaquant : il doit faire son {{score|score}} ou moins dans la compétence qui sert à l’attaque (celle de l’arme, ou Magie, ou Concentration pour un sort).', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (387, 'Jet de défense', NULL, 'Le D100 de la cible qui pare ou esquive. Pour bloquer entièrement le coup, il doit réussir et donner un résultat égal ou inférieur à celui de l’attaquant ; contre une réussite critique, seule une réussite critique compte.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (388, 'Localisation des dégâts', NULL, 'Viser la tête, un bras ou une jambe plutôt que le corps : chaque zone a son malus pour toucher et son effet en plus ; le corps n’a ni malus ni effet.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (389, 'Magie', NULL, 'La compétence liée aux sortilèges et la capacité à les lancer correctement. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (390, 'Manipulation', NULL, 'L''art du mensonge, du sophisme, du détournement de regard et du déplacement de but. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (391, 'Médecine', NULL, 'Liée à tous les soins physiques que la magie ne peut soigner. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (393, 'Négociation', NULL, 'Liée à l''art de négocier quelque chose. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (394, 'Observation', NULL, 'Utiliser sa vue pour bien connaître son environnement en général. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (395, 'Orientation', NULL, 'Pour bien lire une carte et ne pas se perdre. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (396, 'Perception', NULL, '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{arbalete|Arbalète}}, {{distinction|Distinction}}, {{observation|Observation}}, {{orientation|Orientation}} et {{sabotage|Sabotage}}. Renforcée par les magies {{magie-innee|innées}} de la {{magie-de-la-lumiere|Lumière}} ou de l''{{magie-de-lombre|Ombre}}', 'caracteristique:perception', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (397, 'Psychologie', NULL, 'Permet de comprendre la psychologie de sa cible, déceler le mensonge dans le comportement et les paroles. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (398, 'Réflexe', NULL, 'Laisser son corps agir de lui-même. (équivalent de stabilité pour la force) Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (399, 'Réussites / échecs / critiques', '/regles/reussites-echecs-et-critiques/', NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (400, 'Ruse', NULL, '"Parfois, ne pas se battre est la meilleure des victoires" Il est nécessaire de réussir un jet de ruse pour une {{attaque-discrete|attaque discrète}}. Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (401, 'Sabotage', NULL, 'Créer des pièges, les désarmer ou même les retourner contre les ennemis. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (402, 'Social', NULL, '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{diplomatie|Diplomatie}}, {{dressage|Dressage}}, {{intimidation|Intimidation}}, {{manipulation|Manipulation}} et {{negociation|Négociation}}. Renforcée par les magies {{magie-innee|innées}} du {{magie-du-feu|Feu}} ou de l''{{magie-de-leau|Eau}}.', 'caracteristique:social', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (403, 'Stabilité', NULL, 'Être capable de tenir sa position quand le sol tremble, porter une charge longtemps, etc. (équivalent de réflexe pour l’agilité) Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (404, 'Survie', NULL, '"Le corps s’accroche à la vie, telle une sangsue sur une veine" cette compétence est utilisée dans le cas d''un coma. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (405, 'Vie en nature', NULL, 'Comprendre la nature, ses bienfaits. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (406, 'Vigueur', NULL, 'Mieux résister aux {{alteration-detat|altérations d''états}} physiques comme le poison, les maladies ou les brûlures. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (407, 'Volonté', NULL, '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{calme|Calme}}, {{concentration|Concentration}}, {{fermete|Fermeté}}, {{survie|Survie}} et {{vigueur|Vigueur}}. Renforcée par les magies {{magie-innee|innées}} du {{magie-du-vide|Vide}} ou de la {{magie-de-la-necromancie|Nécromancie}}.', 'caracteristique:volonte', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (408, 'Fongoïde', '/races/fongoide/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (409, 'Gémidien', '/races/gemidien/', NULL, 'race:pure', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (410, 'Non-mort', NULL, 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (411, 'Bête', NULL, NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (412, 'Mécanique', NULL, NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (413, 'Démon', NULL, NULL, NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (414, 'Immatériel', NULL, 'Cette créature est naturellement immunisée aux dégâts physiques (armes), seules la magie, une arme spectrale ou une arme sous l’effet d’un {{sort-fer|sort “fer”}} peuvent la toucher.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (415, 'Désarmement', NULL, 'Tout sort, don ou capacité qui fait perdre son arme au porteur.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (416, 'Avantage', NULL, 'On lance deux fois le même jet et on ignore le jet le plus défavorable au lanceur.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (417, 'Super Magie', NULL, 'Réservé aux État de connexion profonde avec sa magie innée, donnant accès à plus de sorts', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (418, 'Mono-magie', NULL, 'Personnage ne disposant que de sa magie innée', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (419, 'Bi-magie', NULL, 'Personnage disposant à la fois de sa {{magie-innee|Magie innée}} et d''une {{magie-acquise|Magie acquise}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (420, 'Mode Hyper 100%', '/regles/le-mode-hyper/', 'État amplifié du {{mode-hyper|Mode Hyper}}. Partage le temps de recharge du mode hyper, a une durée fixe et est plus coûteux en énergie.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (421, 'Loyal Bon', '/regles/alignement/#loyal-bon', 'Le Loyal Bon cherche à faire le bien tout en accordant une grande importance à l’ordre, au devoir et au collectif.', 'alignement:loyal-bon', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (422, 'Loyal Neutre', '/regles/alignement/#loyal-neutre', 'Le Loyal Neutre accorde la priorité à l’ordre, au devoir et au fonctionnement du collectif, sans que le Bien ou le Mal ne constitue nécessairement sa principale préoccupation.', 'alignement:loyal-neutre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (423, 'Loyal Mauvais', '/regles/alignement/#loyal-mauvais', 'Le Loyal Mauvais cherche à satisfaire ses propres intérêts tout en s’appuyant sur l’ordre, la hiérarchie et les règles.', 'alignement:loyal-mauvais', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (424, 'Neutre Bon', '/regles/alignement/#neutre-bon', 'Le Neutre Bon cherche avant tout à faire le bien et à protéger les autres, sans accorder une importance particulière à l’ordre ou à la liberté.', 'alignement:neutre-bon', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (425, 'Neutre', '/regles/alignement/#neutre', 'Le Neutre ne place aucune des quatre tendances au-dessus des autres.', 'alignement:neutre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (426, 'Neutre Mauvais', '/regles/alignement/#neutre-mauvais', 'Le Neutre Mauvais place ses propres intérêts au-dessus de ceux des autres, sans attachement particulier à l’ordre ou au chaos.', 'alignement:neutre-mauvais', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (427, 'Chaotique Bon', '/regles/alignement/#chaotique-bon', 'Le Chaotique Bon cherche à faire le bien tout en accordant une grande importance à la liberté et au libre arbitre.', 'alignement:chaotique-bon', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (428, 'Chaotique Neutre', '/regles/alignement/#chaotique-neutre', 'Le Chaotique Neutre place la liberté individuelle au-dessus de l’ordre et des contraintes imposées par le collectif.', 'alignement:chaotique-neutre', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (429, 'Chaotique Mauvais', '/regles/alignement/#chaotique-mauvais', 'Le Chaotique Mauvais place sa liberté et ses propres désirs au-dessus de toute considération pour les autres.', 'alignement:chaotique-mauvais', NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (430, 'Effet secondaire', NULL, 'Effet secondaire appliqué à un sort, un équipement ou', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (431, 'Consommable', '/ressources/objets-a-la-ceinture/#ceinture-consommables', 'Objet assignable à la ceinture, pour une utilisation pour un {{instant-cast|IC}}.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (432, 'Carquois', '/ressources/objets-a-la-ceinture/#ceinture-carquois', 'Contenant de munition pour un arc, une fronde ou une arbalète.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (433, 'Actif', NULL, 'Compétence ou capacité à activer pendant le tour du personnage. Ne coûte ni {{action|Action}} ni {{instant-cast|IC}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (434, 'Action (Don)', NULL, 'Compétence ou capacité à activer à volonté au prix d''une {{action|Action}}', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (435, 'Passif', NULL, 'Capacité octroyant un bonus permanent.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (436, 'Réaction', NULL, 'Compétence ou capacité utilisable à l''importe quel moment, même en dehors du tour du personnage.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (437, 'Solidité unie', NULL, 'Une armure dont la solidité est unie, perdra le même cran de solidité peu importe l''emplacement touché.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (438, 'Cassé', NULL, 'Pièce d''équipement ou d''arme dont la solidité est réduite à 0. Ne peut plus être utilisée sans réparation préalable.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (439, 'Frappe', NULL, 'Dégâts physiques provoqués par un impact violent pour écraser.', 'degats:frappe', 'degats:frappe');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (440, 'Taille', NULL, 'Dégâts physiques provoqués par une lame tranchante pour découper.', 'degats:taille', 'degats:taille');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (441, 'Estoc', NULL, 'Dégâts physiques provoqués par une pointe transperçant pour planter.', 'degats:estoc', 'degats:estoc');
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (442, 'Vulnérabilité d''Armure', NULL, 'Réduit les {{armure-physique|AP}} et {{armure-magique|AM}} d''une armure face à une attaque d''un type donné :
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (443, 'Résistance d''Armure', NULL, 'Augmente les {{armure-physique|AP}} et {{armure-magique|AM}} d''une armure face à une attaque d''un type donné :
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (444, 'Éthique', NULL, 'Relation d''un personnage entre l''Ordre et la Loi d''un coté, et le Chaos et la Liberté de l''autre.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (445, 'Morale', NULL, 'Relation d''un personnage entre le Bien et l''intérêt général d''un coté, et le Mal et l''intérêt individuel.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (446, 'Roleplay', NULL, 'Action et / ou paroles d''un {{personnage-joueur|PJ}} dans l''interprétation de son personnage dans le cadre du récit, de l''histoire ou du scénario.', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (447, 'Dégâts physiques', NULL, 'Dégâts infligés pas une source matérielle, non magique comme une arme / griffe / Chute  etc..', NULL, NULL);
INSERT INTO repere (mot_cle_id, nom, adresse, definition, couleur, icone) VALUES (448, 'Sonore', NULL, 'Dégâts provoqué par  une onde de choc ou un cri puissant. Inefficace sur un personnage avec surdité 3', NULL, NULL);
